/**
 * OAuditLogPage — 审计日志(event_trail)页。
 *
 * 复用 helios-blocks 的 OEventTimeline + OSearchBar + OFilterChip + ODateRangePicker。
 * 实际数据获取 / 分页由项目实现。
 */
import { useState, type ReactNode } from 'react';
import {
  OEventTimeline,
  OSearchBar,
  OFilterChip,
  type TimelineEvent,
} from '@helios/blocks';

export interface OAuditLogPageProps {
  events: TimelineEvent[];
  title?: string;
  /** 搜索回调(debounced 后)。 */
  onSearchChange?: (query: string) => void;
  /** 状态过滤选项(项目按业务定)。 */
  statusOptions?: { value: string; label: string; count?: number; colorVar?: string }[];
  selectedStatuses?: string[];
  onStatusChange?: (selected: string[]) => void;
  /** 时间过滤 slot(项目自管 date picker)。 */
  timeFilterSlot?: ReactNode;
  /** 点击 event 时回调(打开 detail modal 等)。 */
  onEventClick?: (event: TimelineEvent) => void;
  loading?: boolean;
  emptyMessage?: string;
}

export default function OAuditLogPage({
  events,
  title = '审计日志',
  onSearchChange,
  statusOptions,
  selectedStatuses = [],
  onStatusChange,
  timeFilterSlot,
  onEventClick,
  loading,
  emptyMessage,
}: OAuditLogPageProps) {
  const [search, setSearch] = useState('');

  return (
    <div className="flex flex-col h-full @container">
      <header className="px-6 py-4 border-b border-border">
        <h1 className="text-xl font-semibold mb-3">{title}</h1>
        <div className="flex items-center gap-3 flex-wrap">
          <OSearchBar
            value={search}
            onChange={(v) => {
              setSearch(v);
              onSearchChange?.(v);
            }}
            placeholder="搜索事件..."
            width={280}
          />
          {statusOptions && onStatusChange && (
            <OFilterChip
              label="状态"
              options={statusOptions}
              selected={selectedStatuses}
              onChange={onStatusChange}
              showAll
            />
          )}
          {timeFilterSlot}
        </div>
      </header>
      <div className="flex-1 overflow-auto px-6 py-4">
        {loading ? (
          <div className="text-center py-8 text-muted-foreground text-sm">加载中...</div>
        ) : (
          <OEventTimeline
            events={events}
            onEventClick={onEventClick ?? (() => {})}
            emptyMessage={emptyMessage ?? '暂无事件'}
          />
        )}
      </div>
    </div>
  );
}
