/**
 * OSettingsPage — 设置页面骨架。
 *
 * 设计:左 nav + 右 content,不内置具体设置项。
 * 项目自管 sections(account / security / appearance / notifications / api keys ...)。
 * OUI 提供骨架 + 一些常见 section 的渲染器(项目按需用)。
 */
import type { ReactNode } from 'react';

export interface SettingsSection {
  id: string;
  label: string;
  icon?: ReactNode;
  content: ReactNode;
  /** 标题(content 顶部显示;不传则用 label)。 */
  title?: string;
  /** 描述。 */
  description?: string;
}

export interface OSettingsPageProps {
  sections: SettingsSection[];
  activeId?: string;
  onSectionChange?: (id: string) => void;
  title?: string;
}

export default function OSettingsPage({
  sections,
  activeId,
  onSectionChange,
  title = '设置',
}: OSettingsPageProps) {
  const active = sections.find((s) => s.id === activeId) ?? sections[0];

  if (!active) {
    return (
      <div className="px-6 py-8 text-center text-muted-foreground @container">无设置项</div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <header className="px-6 py-4 border-b border-border">
        <h1 className="text-xl font-semibold">{title}</h1>
      </header>
      <div className="flex flex-1 min-h-0">
        <nav
          aria-label="设置分类"
          className="w-56 shrink-0 border-r border-border overflow-auto p-2"
        >
          <ul className="list-none p-0 m-0 flex flex-col gap-0.5">
            {sections.map((s) => (
              <li key={s.id}>
                <button
                  type="button"
                  onClick={() => onSectionChange?.(s.id)}
                  aria-current={s.id === active.id ? 'page' : undefined}
                  className={[
                    'w-full flex items-center gap-2 px-3 py-1.5 text-sm rounded text-left transition-colors',
                    s.id === active.id
                      ? 'bg-primary/15 text-primary font-medium'
                      : 'hover:bg-muted',
                  ].join(' ')}
                >
                  {s.icon && <span className="shrink-0">{s.icon}</span>}
                  <span className="truncate">{s.label}</span>
                </button>
              </li>
            ))}
          </ul>
        </nav>
        <section className="flex-1 overflow-auto px-6 py-4">
          <header className="mb-4">
            <h2 className="text-base font-semibold">{active.title ?? active.label}</h2>
            {active.description && (
              <p className="text-sm text-muted-foreground mt-1">{active.description}</p>
            )}
          </header>
          <div>{active.content}</div>
        </section>
      </div>
    </div>
  );
}
