import type { ReactNode } from 'react';

export interface OMaintenancePageProps {
  title?: string;
  message?: string;
  estimatedReturn?: string | Date;
  statusLink?: ReactNode;
}

export default function OMaintenancePage({
  title = '系统维护中',
  message = '我们正在升级系统,请稍后再访问。',
  estimatedReturn,
  statusLink,
}: OMaintenancePageProps) {
  const eta =
    estimatedReturn instanceof Date ? estimatedReturn.toLocaleString() : estimatedReturn;
  return (
    <div
      role="status"
      aria-labelledby="oui-maint-title"
      className="min-h-screen flex flex-col items-center justify-center px-4 py-12 bg-background text-foreground @container"
    >
      <div className="text-center max-w-md">
        <div className="text-5xl mb-4" aria-hidden="true">🔧</div>
        <h1 id="oui-maint-title" className="text-xl font-semibold mb-2">
          {title}
        </h1>
        <p className="text-sm text-muted-foreground mb-4">{message}</p>
        {eta && (
          <p className="text-xs text-muted-foreground mb-4">
            预计恢复时间:<span className="font-medium text-foreground">{eta}</span>
          </p>
        )}
        {statusLink}
      </div>
    </div>
  );
}
