/**
 * OUnauthorizedPage — 403 无权限页(角色不足)。
 */
import type { ReactNode } from 'react';

export interface OUnauthorizedPageProps {
  title?: string;
  message?: string;
  requiredRole?: string;
  homeLink?: ReactNode;
  contactAdminLink?: ReactNode;
}

export default function OUnauthorizedPage({
  title = '无权访问',
  message = '你没有访问此页面的权限。',
  requiredRole,
  homeLink,
  contactAdminLink,
}: OUnauthorizedPageProps) {
  return (
    <div
      role="alert"
      aria-labelledby="oui-unauth-title"
      className="min-h-screen flex flex-col items-center justify-center px-4 py-12 bg-background text-foreground @container"
    >
      <div className="text-center max-w-md">
        <div className="text-6xl font-bold text-muted-foreground mb-4" aria-hidden="true">
          403
        </div>
        <h1 id="oui-unauth-title" className="text-xl font-semibold mb-2">
          {title}
        </h1>
        <p className="text-sm text-muted-foreground mb-2">{message}</p>
        {requiredRole && (
          <p className="text-xs text-muted-foreground mb-4">
            需要角色: <span className="font-mono">{requiredRole}</span>
          </p>
        )}
        <div className="flex items-center justify-center gap-2 mt-4">
          {homeLink}
          {contactAdminLink}
        </div>
      </div>
    </div>
  );
}
