/**
 * OSignupPage — 注册页(项目中立复用组件)
 * 与 OLoginPage 统一:用 oui.css 语义 class,不依赖 Tailwind 原子类。
 * v1.7.0:表单逻辑抽到 _AuthRegisterForm,与 OLoginPage 注册 tab 共用
 *         (含密码强度条 + 确认密码一致性校验)。
 */
'use client';

import { type ReactNode } from 'react';
import { OAuthShell } from '../shell/OAuthShell';
import { AuthRegisterForm, type AuthRegisterData } from './_AuthRegisterForm';

export interface OSignupPageProps {
  title?: string;
  subtitle?: string;
  onSubmit?: (data: AuthRegisterData) => void | Promise<void>;
  errorMessage?: string;
  loading?: boolean;
  loginLink?: ReactNode;
  topSlot?: ReactNode;
}

export default function OSignupPage({
  title = '注册',
  subtitle,
  onSubmit,
  errorMessage,
  loading,
  loginLink,
  topSlot,
}: OSignupPageProps) {
  return (
    <OAuthShell title={title} {...(subtitle && { subtitle })} {...(topSlot && { topSlot })}>
      <AuthRegisterForm
        {...(onSubmit && { onSubmit })}
        {...(errorMessage && { errorMessage })}
        {...(loading !== undefined && { loading })}
        {...(loginLink && { footer: loginLink })}
      />
    </OAuthShell>
  );
}
