/**
 * ONotFoundPage — 404 通用页。
 */
import type { ReactNode } from 'react';

export interface ONotFoundPageProps {
  title?: string;
  message?: string;
  /** 返回主页链接 ReactNode(项目传)。 */
  homeLink?: ReactNode;
  /** 自定义底部 slot。 */
  bottomSlot?: ReactNode;
}

export default function ONotFoundPage({
  title = '页面未找到',
  message = '抱歉,你访问的页面不存在或已被移除。',
  homeLink,
  bottomSlot,
}: ONotFoundPageProps) {
  return (
    <div
      role="alert"
      aria-labelledby="oui-notfound-title"
      className="min-h-screen flex flex-col items-center justify-center px-4 py-12 bg-background text-foreground @container"
    >
      <div className="text-center max-w-md">
        <div className="text-6xl font-bold text-muted-foreground mb-4" aria-hidden="true">
          404
        </div>
        <h1 id="oui-notfound-title" className="text-xl font-semibold mb-2">
          {title}
        </h1>
        <p className="text-sm text-muted-foreground mb-6">{message}</p>
        {homeLink && <div>{homeLink}</div>}
        {bottomSlot && <div className="mt-4">{bottomSlot}</div>}
      </div>
    </div>
  );
}
