/**
 * _AuthRegisterForm — 内部共享注册表单(非导出 API,供 OLoginPage 注册 tab 与 OSignupPage 复用)。
 *
 * 设计:
 *   • email + displayName + password(强度条)+ confirm(一致性校验)
 *   • 强度算法搬自 hevi 手写实现,统一进 oui,各项目不再各写
 *   • 纯 oui.css 语义 class,不依赖 Tailwind 原子类
 *   • 提交前做客户端校验(必填/长度/两次一致),通过才回调 onSubmit
 */
'use client';

import { useState, type FormEvent, type ReactNode } from 'react';

export interface AuthRegisterData {
  email: string;
  password: string;
  displayName: string;
}

export interface AuthRegisterFormProps {
  onSubmit?: (data: AuthRegisterData) => void | Promise<void>;
  errorMessage?: string;
  loading?: boolean;
  submitLabel?: string;
  loadingLabel?: string;
  footer?: ReactNode;
}

interface Strength {
  label: string;
  color: string;
  pct: number;
}

/** 密码强度评估(0–4 分映射到四档)。搬自 hevi,统一进 oui。 */
export function passwordStrength(pw: string): Strength {
  let score = 0;
  if (pw.length >= 8) score++;
  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) score++;
  if (/\d/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  const map: Strength[] = [
    { label: '太弱', color: 'var(--destructive)', pct: 25 },
    { label: '弱', color: 'oklch(0.70 0.15 65)', pct: 50 },
    { label: '中', color: 'oklch(0.70 0.14 90)', pct: 75 },
    { label: '强', color: 'var(--success, oklch(0.62 0.18 145))', pct: 100 },
  ];
  return map[Math.min(score, 4) - 1] ?? map[0];
}

export function AuthRegisterForm({
  onSubmit,
  errorMessage,
  loading,
  submitLabel = '注册',
  loadingLabel = '注册中...',
  footer,
}: AuthRegisterFormProps) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [localError, setLocalError] = useState('');

  const strength = password ? passwordStrength(password) : null;
  const mismatch = confirm.length > 0 && confirm !== password;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setLocalError('');
    if (!email.trim() || !password || !displayName.trim()) {
      setLocalError('请填写完整信息');
      return;
    }
    if (password.length < 8) {
      setLocalError('密码至少 8 位');
      return;
    }
    if (password !== confirm) {
      setLocalError('两次密码不一致');
      return;
    }
    onSubmit?.({ email: email.trim(), password, displayName: displayName.trim() });
  };

  const shownError = errorMessage || localError;

  return (
    <form onSubmit={submit} className="oui-form" noValidate>
      <label className="oui-label">
        显示名
        <input
          type="text" required autoComplete="name"
          value={displayName} onChange={e => setDisplayName(e.target.value)}
          placeholder="你的昵称"
          className="oui-input"
        />
      </label>

      <label className="oui-label">
        邮箱 / Email
        <input
          type="email" required autoComplete="email"
          value={email} onChange={e => setEmail(e.target.value)}
          placeholder="your@email.com"
          className="oui-input"
        />
      </label>

      <label className="oui-label">
        密码 / Password
        <input
          type="password" required autoComplete="new-password" minLength={8}
          value={password} onChange={e => setPassword(e.target.value)}
          placeholder="至少 8 位"
          className="oui-input"
        />
        {strength && (
          <div className="oui-strength" aria-hidden="true">
            <div className="oui-strength-track">
              <div
                className="oui-strength-fill"
                style={{ width: `${strength.pct}%`, background: strength.color }}
              />
            </div>
            <span className="oui-strength-label" style={{ color: strength.color }}>
              {strength.label}
            </span>
          </div>
        )}
      </label>

      <label className="oui-label">
        确认密码
        <input
          type="password" required autoComplete="new-password"
          value={confirm} onChange={e => setConfirm(e.target.value)}
          placeholder="再次输入密码"
          className="oui-input"
          aria-invalid={mismatch}
        />
        {mismatch && <span className="oui-field-error">两次密码不一致</span>}
      </label>

      {shownError && <div role="alert" className="oui-error-alert">{shownError}</div>}

      <button type="submit" disabled={loading} className="oui-btn-primary oui-w-full">
        {loading ? loadingLabel : submitLabel}
      </button>

      {footer && <div className="oui-text-xs oui-text-center">{footer}</div>}
    </form>
  );
}
